import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
class LoyaltyRewardManagementScreen extends StatelessWidget { const LoyaltyRewardManagementScreen({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Loyalty Rewards')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('loyalty_rewards').snapshots(),builder:(c,s){return ListView(children:(s.data?.docs??[]).map((d)=>SwitchListTile(title:Text(d.data()['name']??d.id),subtitle:Text('${d.data()['requiredPoints']??0} points'),value:d.data()['status']=='Active',onChanged:(v)=>d.reference.set({'status':v?'Active':'Inactive','updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true)))).toList());}));}
